#!/usr/bin/env python3
"""Print report file names in numerical order, one per line."""

import os
import re


def report_sort_key(filename: str) -> tuple:
    """Extract the numeric part of report-N.txt for sorting."""
    match = re.search(r'report-(\d+)\.txt$', filename)
    if match:
        return (int(match.group(1)),)
    return (float('inf'),)


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'reports')
    files = [f for f in os.listdir(reports_dir) if os.path.isfile(os.path.join(reports_dir, f))]
    files.sort(key=report_sort_key)
    for f in files:
        print(f)


if __name__ == '__main__':
    main()

